TD.add("databases", [

{t:"SQL", a:"Structured Query Language", d:"The standard language for defining, querying and modifying data in relational databases — declarative, so you describe the result you want, not how to fetch it.", l:"core", g:["sql","query","relational"],
 b:["SQL is declarative. You write `SELECT name FROM users WHERE age > 30` and the database's query planner decides whether to scan the table, use an index, or reorder joins. That separation is why the same query can get dramatically faster after adding an index, without a single character changing.",
    "It is not one monolithic language but five families of commands — DDL, DML, DQL, DCL and TCL — that happen to share a grammar. Every relational engine implements the ANSI core and then adds its own dialect on top, so a query that works on PostgreSQL may need adjusting for SQL Server."],
 k:["Declarative: you state the goal, the optimiser picks the plan.",
    "Five command families: **DDL** structure, **DML** data, **DQL** reading, **DCL** permissions, **TCL** transactions.",
    "Every engine has dialect differences — date functions and pagination especially.",
    "Set-based thinking beats row-by-row loops almost every time."],
 x:{lang:"sql", code:'SELECT c.country,\n       COUNT(*)        AS orders,\n       SUM(o.total)    AS revenue\nFROM orders o\nJOIN customers c ON c.id = o.customer_id\nWHERE o.created_at >= DATE \'2024-01-01\'\nGROUP BY c.country\nHAVING COUNT(*) > 10\nORDER BY revenue DESC\nLIMIT 20;'},
 dg:"sql-sublanguages",
 r:["DDL","DML","DQL","DCL","TCL","Relational Database","Index","Join"]},

{t:"DDL", a:"Data Definition Language", d:"The SQL commands that define and change the structure of a database: tables, columns, indexes, schemas.", l:"core", g:["sql","schema"],
 b:["DDL is about shape, not contents. `CREATE`, `ALTER`, `DROP`, `TRUNCATE` and `RENAME` build and reshape the container that data lives in. In most engines DDL statements are implicitly committed — issuing one ends the current transaction — which is a nasty surprise the first time it happens in a script.",
    "In production, DDL is the riskiest SQL you will run. Adding a column with a default can rewrite an entire table and lock it for minutes; dropping one is unrecoverable without a backup. Migration tools exist precisely so schema changes are reviewed, versioned and reversible."],
 k:["`CREATE`, `ALTER`, `DROP`, `TRUNCATE`, `RENAME`.",
    "Usually auto-commits — you cannot roll it back in most engines.",
    "`TRUNCATE` empties a table quickly but is DDL, not DML, so no row-level rollback.",
    "Always run schema changes through a versioned migration tool."],
 x:{lang:"sql", code:'CREATE TABLE orders (\n  id          BIGSERIAL PRIMARY KEY,\n  customer_id BIGINT NOT NULL REFERENCES customers(id),\n  total       NUMERIC(12,2) NOT NULL CHECK (total >= 0),\n  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE INDEX idx_orders_customer ON orders (customer_id);'},
 r:["SQL","DML","Database Migration","Schema"]},

{t:"DML", a:"Data Manipulation Language", d:"The SQL commands that add, change and remove rows: INSERT, UPDATE, DELETE, MERGE.", l:"core", g:["sql","write"],
 b:["DML changes contents, not structure. Unlike DDL it participates fully in transactions, so an `UPDATE` inside a transaction can be rolled back if something later fails. That is the whole reason transactions exist.",
    "The classic production incident is an `UPDATE` or `DELETE` without a `WHERE` clause. The habit that prevents it: write the statement as a `SELECT` first, check the row count, then convert it — inside an explicit transaction you can still roll back."],
 k:["`INSERT`, `UPDATE`, `DELETE`, `MERGE` (also called upsert).",
    "Transactional — can be rolled back before commit.",
    "Always write the `WHERE` clause before the `SET` clause.",
    "`RETURNING` (PostgreSQL) gives you the changed rows back in one round trip."],
 x:{lang:"sql", code:'BEGIN;\n\nUPDATE accounts SET balance = balance - 100 WHERE id = 1;\nUPDATE accounts SET balance = balance + 100 WHERE id = 2;\n\n-- verify before committing\nSELECT id, balance FROM accounts WHERE id IN (1, 2);\n\nCOMMIT;'},
 r:["SQL","DDL","Transaction","TCL"]},

{t:"DQL", a:"Data Query Language", d:"The read side of SQL — in practice, the SELECT statement and everything attached to it.", l:"core", g:["sql","read"],
 b:["DQL is a single command with enormous depth. `SELECT` carries `FROM`, `JOIN`, `WHERE`, `GROUP BY`, `HAVING`, `WINDOW`, `ORDER BY` and `LIMIT`, and the logical order in which they execute is not the order in which they are written: `FROM` and `JOIN` first, then `WHERE`, then `GROUP BY`, then `HAVING`, then `SELECT`, then `ORDER BY`, then `LIMIT`.",
    "Knowing that order explains several beginner puzzles — why you cannot use a `SELECT` alias in `WHERE`, and why `WHERE` filters rows while `HAVING` filters groups."],
 k:["Logical order: FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT.",
    "`WHERE` filters rows before grouping; `HAVING` filters after.",
    "Column aliases are not visible to `WHERE` because `SELECT` runs later.",
    "`SELECT *` in production code is a future outage waiting for a schema change."],
 r:["SQL","Join","Aggregate Function","Window Function"]},

{t:"DCL", a:"Data Control Language", d:"The SQL commands that grant and revoke permissions on database objects.", l:"intermediate", g:["sql","security"],
 b:["`GRANT` and `REVOKE` control who can do what to which object. Well-run databases give applications a role with exactly the privileges it needs — often `SELECT`, `INSERT`, `UPDATE` on specific tables and nothing else — rather than connecting as a superuser.",
    "This is the principle of least privilege applied at the data layer. It is also the difference between a SQL injection that leaks one table and one that drops the schema."],
 k:["`GRANT` gives privileges; `REVOKE` removes them.",
    "Grant to roles, then assign roles to users — never grant to individuals directly.",
    "Application accounts should never be superusers.",
    "Row-level security narrows access further, per row rather than per table."],
 x:{lang:"sql", code:'CREATE ROLE app_read;\nGRANT SELECT ON ALL TABLES IN SCHEMA public TO app_read;\n\nCREATE ROLE app_write;\nGRANT SELECT, INSERT, UPDATE ON orders TO app_write;\n\nREVOKE DELETE ON orders FROM app_write;'},
 r:["SQL","Principle of Least Privilege","Authorisation","Role-Based Access Control"]},

{t:"TCL", a:"Transaction Control Language", d:"The SQL commands that mark transaction boundaries: COMMIT, ROLLBACK, SAVEPOINT.", l:"intermediate", g:["sql","transaction"],
 b:["TCL is how you tell the database that a group of statements is one logical unit. `BEGIN` opens it, `COMMIT` makes every change durable, `ROLLBACK` discards all of them, and `SAVEPOINT` creates an intermediate marker you can roll back to without abandoning the whole transaction.",
    "Most drivers run in autocommit mode by default, wrapping each statement in its own transaction. That is fine for single statements and completely wrong for a money transfer."],
 k:["`BEGIN` / `COMMIT` / `ROLLBACK` / `SAVEPOINT` / `RELEASE`.",
    "Autocommit is on by default in most clients — opt out explicitly for multi-statement work.",
    "Long-running transactions hold locks and block others; keep them short.",
    "A rollback is not a failure — it is the mechanism working correctly."],
 r:["Transaction","ACID","DML","Isolation Level"]},

{t:"Relational Database", d:"A database that stores data in tables of rows and columns, with relationships expressed through keys and enforced by constraints.", l:"core", g:["database","relational"],
 b:["The relational model, defined by Edgar Codd in 1970, separates the logical structure of data from how it is physically stored. Data lives in tables; relationships are values (foreign keys) rather than pointers; and a query language operates on sets rather than records one at a time.",
    "Its enduring advantage is that correctness is the database's job, not the application's. Constraints, foreign keys and transactions mean invalid data is rejected at the door regardless of which of your five services tried to write it."],
 k:["Tables, rows, columns; relationships via primary and foreign keys.",
    "Constraints enforce correctness centrally, not per application.",
    "ACID transactions make multi-row changes safe.",
    "PostgreSQL, MySQL, SQL Server, Oracle and SQLite are the main engines."],
 dg:"star-schema",
 r:["SQL","NoSQL","Primary Key","Foreign Key","ACID","Normalisation"]},

{t:"Primary Key", d:"The column or set of columns that uniquely identifies each row in a table.", l:"core", g:["schema","keys"],
 b:["A primary key must be unique and never null, and in nearly every engine it also creates a clustered or unique index that the database uses to find rows fast. Every table should have one; a table without a primary key is a bag of rows you cannot reliably update or reference.",
    "The recurring design argument is natural versus surrogate keys. A natural key uses real data (an email address, an ISBN). A surrogate key is a meaningless generated value — an auto-increment integer or a UUID. Surrogate keys win in most systems because real-world identifiers change, and changing a primary key cascades everywhere."],
 k:["Unique, non-null, one per table.",
    "Surrogate keys (BIGSERIAL, UUID) beat natural keys because real data changes.",
    "Sequential integers index better; UUIDv7 gives uniqueness with time ordering.",
    "Composite primary keys are legitimate for junction tables."],
 x:{lang:"sql", code:'-- surrogate key\nCREATE TABLE users (\n  id    BIGSERIAL PRIMARY KEY,\n  email TEXT NOT NULL UNIQUE\n);\n\n-- composite key on a junction table\nCREATE TABLE user_roles (\n  user_id BIGINT REFERENCES users(id),\n  role_id BIGINT REFERENCES roles(id),\n  PRIMARY KEY (user_id, role_id)\n);'},
 r:["Foreign Key","Index","Composite Key"]},

{t:"Foreign Key", d:"A column that references the primary key of another table, so the database itself enforces the relationship.", l:"core", g:["schema","keys"],
 b:["A foreign key constraint means the database will reject an order whose `customer_id` does not exist, and will refuse to delete a customer that still has orders (unless you tell it to cascade). That guarantee is called referential integrity, and it holds no matter which application or ad-hoc script tried to break it.",
    "Some high-scale systems drop foreign keys for write throughput and enforce relationships in application code. That is a real trade-off, made deliberately — it is not a default worth copying."],
 k:["Enforces referential integrity at the database, not in every application.",
    "`ON DELETE CASCADE`, `RESTRICT`, `SET NULL` define what happens to children.",
    "Foreign key columns should almost always be indexed — most engines do not do it for you.",
    "Adds a small write cost; occasionally dropped deliberately at very high scale."],
 x:{lang:"sql", code:'CREATE TABLE orders (\n  id          BIGSERIAL PRIMARY KEY,\n  customer_id BIGINT NOT NULL\n                REFERENCES customers(id)\n                ON DELETE RESTRICT\n);\n\nCREATE INDEX idx_orders_customer ON orders (customer_id);'},
 r:["Primary Key","Referential Integrity","Index","Relational Database"]},

{t:"Composite Key", d:"A key made of two or more columns that together identify a row uniquely.", l:"intermediate", g:["schema","keys"],
 b:["Composite keys are natural for junction tables, where the pair `(user_id, role_id)` is the identity. They also matter for indexing: a composite index on `(a, b)` can serve queries filtering on `a` alone, or on `a` and `b`, but not on `b` alone. That is the leftmost prefix rule, and it decides column order.",
    "Put the most selective and most frequently filtered column first, and match the index order to the query patterns you actually run."],
 k:["Order matters: an index on (a, b) serves a, and a+b, but not b alone.",
    "Natural fit for many-to-many junction tables.",
    "Adds width to every secondary index that references it.",
    "Check the query plan before assuming your composite index is used."],
 r:["Primary Key","Index","Query Plan"]},

{t:"Index", d:"An auxiliary data structure that lets the database find matching rows without reading the whole table.", l:"core", g:["performance","query"],
 b:["Without an index the engine scans every row — O(n). With a B-tree index it walks a shallow tree — O(log n) — so a lookup in a hundred million rows takes three or four page reads instead of a hundred million. This is the single biggest lever on query performance, and most slow queries are a missing index.",
    "Indexes are not free. Every insert, update and delete must maintain them, they consume disk, and an unused index is pure overhead. The craft is choosing few, well-designed indexes that match real query patterns rather than adding one per column."],
 k:["Turns O(n) scans into O(log n) lookups.",
    "Slows writes and consumes storage — index deliberately, not exhaustively.",
    "A covering index contains every column the query needs, avoiding a table lookup.",
    "Read the execution plan to confirm the index is actually used."],
 x:{lang:"sql", code:'-- before: sequential scan over 40 million rows\nEXPLAIN ANALYZE\nSELECT * FROM events WHERE user_id = 42 AND type = \'login\';\n\nCREATE INDEX idx_events_user_type ON events (user_id, type);\n\n-- after: index scan, milliseconds'},
 dg:"index-scan",
 r:["B-Tree","Query Plan","Full Table Scan"]},

{t:"B-Tree", d:"The balanced tree structure behind almost every database index, keeping lookups shallow and ranges cheap.", l:"intermediate", g:["performance","data-structure"],
 b:["A B-tree (specifically a B+ tree in most databases) stores keys in sorted order across wide nodes sized to match a disk page. Because each node holds hundreds of keys, the tree stays extremely shallow — three or four levels is enough for hundreds of millions of rows — so any lookup is a handful of page reads.",
    "Leaf nodes are linked together, which is why B-trees serve range scans, `ORDER BY` and `BETWEEN` efficiently. Hash indexes are faster for exact equality but cannot do any of that."],
 k:["Balanced and shallow: three or four levels covers hundreds of millions of rows.",
    "Sorted leaves make range queries and ORDER BY cheap.",
    "Node size is matched to the disk page size.",
    "Hash indexes beat it for pure equality but cannot do ranges."],
 dg:"btree",
 r:["Index","Query Plan","Hash Table"]},

{t:"Join", d:"A SQL operation that combines rows from two tables based on a matching condition.", l:"core", g:["sql","query"],
 b:["`INNER JOIN` keeps only rows that match on both sides. `LEFT JOIN` keeps everything from the left table, filling nulls where the right has no match. `RIGHT JOIN` mirrors that, and `FULL OUTER JOIN` keeps everything from both. `CROSS JOIN` produces every combination, which is almost always a mistake when it appears accidentally.",
    "The most common bug is filtering a left-joined table in `WHERE` instead of in the `ON` clause — that turns the outer join back into an inner join, silently dropping the rows you were trying to preserve."],
 k:["INNER keeps matches; LEFT keeps all of the left side plus nulls.",
    "Filtering the right table in `WHERE` converts a LEFT JOIN into an INNER JOIN.",
    "Join on indexed columns or the planner will resort to a hash or nested-loop scan.",
    "Duplicate rows after a join usually mean the join key is not unique."],
 x:{lang:"sql", code:'-- keeps customers with zero orders\nSELECT c.name, COUNT(o.id) AS order_count\nFROM customers c\nLEFT JOIN orders o\n       ON o.customer_id = c.id\n      AND o.status = \'paid\'      -- filter belongs here\nGROUP BY c.name;'},
 dg:"joins",
 r:["SQL","DQL","Index","Subquery"]},

{t:"Subquery", d:"A query nested inside another query, used as a value, a set, or a derived table.", l:"intermediate", g:["sql","query"],
 b:["A scalar subquery returns one value and can sit in `SELECT` or `WHERE`. An `IN` subquery returns a set to test membership. A correlated subquery references the outer query and re-runs for each outer row — which is where performance disappears if the row count is large.",
    "Most correlated subqueries can be rewritten as a join or a window function, usually with a dramatic speed-up. `EXISTS` is generally preferable to `IN` when checking for presence, because it can stop at the first match."],
 k:["Correlated subqueries re-execute per outer row — the usual performance trap.",
    "`EXISTS` short-circuits; `IN` may materialise the whole set.",
    "`NOT IN` behaves surprisingly with NULLs — prefer `NOT EXISTS`.",
    "A derived table in `FROM` is often clearer as a CTE."],
 r:["Join","Common Table Expression","Query Plan"]},

{t:"Common Table Expression", a:"CTE / WITH clause", d:"A named temporary result set defined at the top of a query, making complex SQL readable and enabling recursion.", l:"intermediate", g:["sql","query"],
 b:["A CTE lets you name a step: `WITH recent_orders AS (...) SELECT ... FROM recent_orders`. Chaining several turns a deeply nested query into a sequence of readable stages. Recursive CTEs go further, letting you walk hierarchies — org charts, category trees, graph paths — in pure SQL.",
    "Historically PostgreSQL treated CTEs as optimisation fences (materialising them), which could hurt performance; since version 12 they can be inlined, and `MATERIALIZED` / `NOT MATERIALIZED` gives explicit control."],
 k:["Names a step, turning nested queries into readable stages.",
    "`WITH RECURSIVE` walks trees and graphs without application code.",
    "Modern PostgreSQL inlines CTEs unless you say `MATERIALIZED`.",
    "Great for readability; check the plan before assuming it is free."],
 x:{lang:"sql", code:'WITH RECURSIVE subordinates AS (\n  SELECT id, name, manager_id FROM employees WHERE id = 1\n  UNION ALL\n  SELECT e.id, e.name, e.manager_id\n  FROM employees e\n  JOIN subordinates s ON e.manager_id = s.id\n)\nSELECT * FROM subordinates;'},
 r:["Subquery","Window Function","SQL"]},

{t:"View", d:"A stored query that behaves like a table, computed fresh every time it is read.", l:"intermediate", g:["sql","schema"],
 b:["A view is a saved `SELECT`. Querying it runs the underlying query, so the data is always current and no extra storage is used. Views are useful for hiding join complexity, presenting a stable interface over a changing schema, and restricting access to a subset of columns or rows.",
    "They do not make anything faster — a view over a slow query is still a slow query. For that you need a materialised view."],
 k:["Always current, because it executes on read.",
    "Consumes no storage and provides no speed-up.",
    "Useful as a stable public interface over an evolving schema.",
    "Some views are updatable; most non-trivial ones are read-only."],
 r:["Materialised View","SQL","Schema"]},

{t:"Materialised View", d:"A view whose results are physically stored, so reads are fast but data can be stale until refreshed.", l:"intermediate", g:["sql","performance"],
 b:["A materialised view computes its query once and writes the result to disk. Reads then hit precomputed rows, which can turn a thirty-second analytical aggregation into a millisecond lookup. The trade is staleness: the data is only as fresh as the last refresh.",
    "Refresh strategies range from full recomputation on a schedule to incremental refresh on write. It is essentially a cache managed by the database, with the same invalidation questions any cache raises."],
 k:["Stores results physically — fast reads, stale data.",
    "Refresh on a schedule, on demand, or incrementally.",
    "`REFRESH ... CONCURRENTLY` in PostgreSQL avoids locking readers.",
    "Effectively a database-managed cache, with the same trade-offs."],
 r:["View","Caching","OLAP"]},

{t:"Stored Procedure", d:"Reusable procedural code stored and executed inside the database engine.", l:"intermediate", g:["sql","procedural"],
 b:["Stored procedures put logic next to the data, eliminating round trips: a loop that would need a thousand network calls from the application runs entirely inside the server. They can also enforce rules regardless of which client connects.",
    "The downsides are real: business logic in the database is harder to version control, test, and review, and it locks you to one vendor's procedural dialect. Most teams now keep logic in the application and use procedures only for data-heavy batch work."],
 k:["Removes network round trips for data-intensive loops.",
    "Vendor-specific: PL/pgSQL, T-SQL and PL/SQL are not portable.",
    "Harder to version, test and code-review than application code.",
    "Best reserved for bulk data operations, not business rules."],
 r:["Trigger","SQL"]},

{t:"Trigger", d:"Code the database runs automatically in response to an insert, update or delete.", l:"intermediate", g:["sql","procedural"],
 b:["Triggers fire before or after a row change and can enforce invariants, maintain audit tables, or keep denormalised copies in sync. Because they are invisible from the application, they guarantee behaviour no client can bypass.",
    "That invisibility is also the danger. A slow trigger silently slows every write; a trigger that writes to another table with its own trigger creates cascades that are painful to debug. Use them for auditing and integrity, rarely for business logic."],
 k:["Runs automatically — no client can skip it.",
    "BEFORE triggers can modify the row; AFTER triggers see the final state.",
    "Invisible in application code, which makes debugging harder.",
    "Ideal for audit trails; risky for business rules."],
 r:["Stored Procedure","Audit Log","Referential Integrity"]},

{t:"Transaction", d:"A group of database operations treated as a single indivisible unit that either fully succeeds or fully fails.", l:"core", g:["transaction","acid"],
 b:["The canonical example is a bank transfer: debit one account, credit another. If the process crashes between the two, a transaction guarantees neither happened. Everything between `BEGIN` and `COMMIT` is atomic, and `ROLLBACK` discards all of it.",
    "Transactions hold locks for their duration, so a transaction left open across a slow HTTP call can block every other writer. Keep them short, keep external calls outside them, and set an explicit timeout."],
 k:["All-or-nothing: partial completion is impossible.",
    "Holds locks until commit — long transactions block other writers.",
    "Never make network calls inside an open transaction.",
    "Isolation level controls what concurrent transactions can observe."],
 dg:"acid",
 r:["ACID","Isolation Level","TCL","Deadlock"]},

{t:"ACID", d:"The four guarantees a transactional database provides: Atomicity, Consistency, Isolation, Durability.", l:"core", g:["transaction","theory"],
 b:["**Atomicity** — the transaction happens entirely or not at all. **Consistency** — it moves the database from one valid state to another, respecting every constraint. **Isolation** — concurrent transactions do not see each other's half-finished work. **Durability** — once committed, it survives a crash, because it was written to a durable log first.",
    "These are strong guarantees and they cost coordination, which is why distributed systems often relax them. But when the data is money, inventory or medical records, ACID is what lets you sleep."],
 k:["Atomicity — all or nothing.",
    "Consistency — constraints hold before and after.",
    "Isolation — concurrent transactions do not interfere.",
    "Durability — committed means survived the power cut."],
 dg:"acid",
 r:["Transaction","BASE","Isolation Level","CAP Theorem"]},

{t:"BASE", d:"The relaxed alternative to ACID used by many distributed stores: Basically Available, Soft state, Eventually consistent.", l:"intermediate", g:["distributed","theory"],
 b:["BASE accepts temporary inconsistency in exchange for availability and scale. A write may be visible on one replica before another; given enough time and no new writes, all replicas converge. That is eventual consistency.",
    "It is the right model for a social feed, a product catalogue or a view counter, where a few seconds of staleness harms nobody. It is the wrong model for account balances and seat reservations, where two clients reading stale data can both spend the same money."],
 k:["Availability and partition tolerance over immediate consistency.",
    "Replicas converge eventually, not instantly.",
    "Great for feeds, catalogues and counters; wrong for balances and inventory.",
    "Conflict resolution (last write wins, CRDTs) becomes an application concern."],
 r:["ACID","CAP Theorem","Eventual Consistency","NoSQL"]},

{t:"Isolation Level", d:"A setting that controls how much of other in-flight transactions a transaction can see.", l:"advanced", g:["transaction","concurrency"],
 b:["The SQL standard defines four levels. **Read Uncommitted** allows dirty reads. **Read Committed** — the common default — only sees committed data, but the same query can return different results twice in one transaction. **Repeatable Read** stops that, but phantom rows can still appear. **Serializable** behaves as if transactions ran one after another.",
    "Higher isolation means more locking or more aborted transactions. Choose the weakest level that is still correct for the operation, and be aware that engines differ: PostgreSQL's Repeatable Read is snapshot isolation, and MySQL's default is Repeatable Read while PostgreSQL's is Read Committed."],
 k:["Dirty read, non-repeatable read and phantom read are the three anomalies.",
    "PostgreSQL defaults to Read Committed; MySQL InnoDB to Repeatable Read.",
    "Serializable is correct by construction but increases retries and contention.",
    "`SELECT ... FOR UPDATE` locks specific rows without raising the whole level."],
 r:["Transaction","ACID","Deadlock","Optimistic Locking"]},

{t:"Deadlock", d:"Two or more transactions each holding a lock the other needs, so none can proceed.", l:"intermediate", g:["concurrency","transaction"],
 b:["Transaction A locks row 1 and wants row 2; transaction B locks row 2 and wants row 1. Neither can continue. Databases detect this cycle and kill one transaction, returning a deadlock error to that client.",
    "The reliable fix is ordering: if every transaction acquires locks in a consistent order — say, always ascending by primary key — the cycle cannot form. Shorter transactions and appropriate indexes (which reduce the number of rows locked) also help substantially."],
 k:["The engine detects the cycle and aborts one victim transaction.",
    "Acquire locks in a consistent order everywhere to prevent cycles.",
    "Shorter transactions hold fewer locks for less time.",
    "Make the application retry the victim — deadlocks are expected, not exceptional."],
 r:["Transaction","Isolation Level","Race Condition","Concurrency"]},

{t:"Normalisation", a:"Database Normalisation", d:"Organising tables so each fact is stored in exactly one place, eliminating redundancy and update anomalies.", l:"core", g:["modelling","schema"],
 b:["Normalisation proceeds through normal forms. **1NF**: no repeating groups, every cell holds one value. **2NF**: no partial dependency on part of a composite key. **3NF**: no non-key column depends on another non-key column. Most production schemas stop at 3NF or BCNF.",
    "The point is not academic tidiness. If a customer's address is stored on every order, changing it means updating a thousand rows and any missed row is now wrong. Normalisation makes that impossible by storing the address once and referencing it."],
 k:["1NF: atomic values, no repeating groups.",
    "2NF: no partial dependencies on part of a composite key.",
    "3NF: no transitive dependencies between non-key columns.",
    "Eliminates insert, update and delete anomalies — the real payoff."],
 dg:"normalization",
 r:["Denormalisation","Relational Database","Foreign Key","Star Schema"]},

{t:"Denormalisation", d:"Deliberately duplicating data to avoid joins and make reads faster.", l:"intermediate", g:["modelling","performance"],
 b:["Once a schema is correctly normalised, some read paths become expensive — five joins to render one page. Denormalisation copies a column, precomputes a count, or stores a JSON blob so that read can be a single lookup.",
    "The cost is that you now own consistency. Every write path must update every copy, and any that forgets creates data that disagrees with itself. Denormalise deliberately, in response to a measured problem, and write down where the duplicates live."],
 k:["Trades write complexity and storage for read speed.",
    "Every duplicate is a consistency obligation you now own.",
    "Common in analytics schemas, read replicas and caches.",
    "Normalise first; denormalise only when you have measured the need."],
 r:["Normalisation","Caching","Star Schema","OLAP"]},

{t:"Schema", d:"The formal definition of a database's structure: its tables, columns, types, constraints and relationships.", l:"core", g:["modelling","schema"],
 b:["A schema is a contract. It tells every reader and writer what shape the data has, and the database enforces it — a column typed `NUMERIC(12,2) NOT NULL` cannot hold the string `unknown`. In PostgreSQL, `schema` also means a namespace grouping tables inside a database.",
    "Schema-on-write databases validate at insert time; schema-on-read systems (data lakes, document stores) accept anything and interpret it at query time. Both approaches work; the difference is where the errors surface."],
 k:["Defines tables, types, keys and constraints — and enforces them.",
    "Schema-on-write validates at insert; schema-on-read at query.",
    "In PostgreSQL a schema is also a namespace within a database.",
    "Schema changes are managed through versioned migrations."],
 r:["DDL","Database Migration","Normalisation","Data Lake"]},

{t:"Database Migration", d:"A versioned, ordered script that changes the database schema alongside application code.", l:"core", g:["schema","tooling"],
 b:["Migrations put schema changes in version control next to the code that depends on them. Each migration has an identifier, runs exactly once, and is applied in order, so any environment can be brought to the current schema deterministically. Flyway, Liquibase, Alembic, Prisma Migrate and Rails migrations all implement this.",
    "The hard part is zero-downtime deploys, where old and new code run simultaneously. The standard solution is expand-and-contract: add the new column, backfill it, deploy code that writes both, switch reads, then remove the old column in a later release."],
 k:["Versioned, ordered, applied once — reproducible across environments.",
    "Expand-and-contract enables schema changes with no downtime.",
    "Always pair a migration with a tested rollback plan.",
    "Backfills on large tables must be batched or they will lock the table."],
 r:["Schema","DDL","CI/CD","Blue-Green Deployment"]},

{t:"Referential Integrity", d:"The guarantee that every foreign key points at a row that actually exists.", l:"intermediate", g:["schema","integrity"],
 b:["Referential integrity prevents orphan records: an order whose customer was deleted, a comment on a post that no longer exists. The database enforces it through foreign key constraints, rejecting writes and deletes that would break the relationship.",
    "Cascade rules define the behaviour on delete. `RESTRICT` refuses, `CASCADE` deletes children too, `SET NULL` orphans them deliberately. `CASCADE` is convenient and occasionally catastrophic — one delete can remove far more than intended."],
 k:["No orphan rows: a foreign key must reference an existing row.",
    "`ON DELETE CASCADE` can delete far more than you expect — use with care.",
    "Enforced centrally, so no client can bypass it.",
    "Distributed systems often trade this away for scale."],
 r:["Foreign Key","Relational Database","Constraint"]},

{t:"Constraint", d:"A rule the database enforces on data, rejecting any write that would violate it.", l:"core", g:["schema","integrity"],
 b:["`NOT NULL`, `UNIQUE`, `CHECK`, `PRIMARY KEY`, `FOREIGN KEY` and `DEFAULT` are the standard set. A `CHECK` constraint can encode real business rules — a discount between 0 and 100, an end date after a start date — and the database will enforce them for every writer forever.",
    "Application-level validation is still worth having for good error messages, but it is not a substitute. Constraints are the only validation that a migration script, an ad-hoc psql session or a second service cannot bypass."],
 k:["`NOT NULL`, `UNIQUE`, `CHECK`, `PRIMARY KEY`, `FOREIGN KEY`, `DEFAULT`.",
    "The only validation no client can skip.",
    "`CHECK` constraints can express genuine business rules.",
    "Adding a constraint to an existing table requires validating existing rows."],
 x:{lang:"sql", code:'ALTER TABLE bookings\n  ADD CONSTRAINT valid_dates\n  CHECK (ends_at > starts_at);\n\nALTER TABLE products\n  ADD CONSTRAINT positive_price\n  CHECK (price >= 0);'},
 r:["Referential Integrity","Schema","Primary Key"]},

{t:"Aggregate Function", d:"A function that collapses many rows into a single summary value.", l:"core", g:["sql","query"],
 b:["`COUNT`, `SUM`, `AVG`, `MIN` and `MAX` are the core five. Combined with `GROUP BY` they turn raw rows into summaries per group. `HAVING` then filters those groups, as opposed to `WHERE` which filters rows before grouping.",
    "The classic gotchas: aggregates ignore NULLs (so `AVG` divides by the count of non-null values), `COUNT(*)` counts rows while `COUNT(col)` counts non-null values, and every non-aggregated column in the `SELECT` must appear in `GROUP BY`."],
 k:["`COUNT`, `SUM`, `AVG`, `MIN`, `MAX` — plus statistical ones per engine.",
    "NULLs are skipped, which changes what `AVG` actually divides by.",
    "`COUNT(*)` counts rows; `COUNT(col)` counts non-nulls.",
    "`WHERE` filters rows, `HAVING` filters groups."],
 r:["Window Function","DQL","Group By"]},

{t:"Window Function", d:"A function that computes across a set of related rows while keeping every row in the output.", l:"advanced", g:["sql","analytics"],
 b:["Where `GROUP BY` collapses rows, a window function computes over a frame and returns a value on every row. `ROW_NUMBER()`, `RANK()`, `LAG()`, `LEAD()` and running totals via `SUM() OVER (...)` are the workhorses.",
    "They solve problems that are painful otherwise: top-N per group, period-over-period comparison, running balances, deduplication by picking the newest row per key. Learning `OVER (PARTITION BY ... ORDER BY ...)` is one of the highest-leverage SQL skills there is."],
 k:["Keeps every row, unlike GROUP BY.",
    "`PARTITION BY` splits into groups; `ORDER BY` defines order inside each.",
    "`ROW_NUMBER()` + a filter is the standard top-N-per-group pattern.",
    "`LAG`/`LEAD` compare a row with its neighbours without a self-join."],
 x:{lang:"sql", code:'SELECT *\nFROM (\n  SELECT o.*,\n         ROW_NUMBER() OVER (\n           PARTITION BY customer_id\n           ORDER BY created_at DESC\n         ) AS rn\n  FROM orders o\n) t\nWHERE rn = 1;   -- newest order per customer'},
 r:["Aggregate Function","Common Table Expression","OLAP"]},

{t:"Group By", d:"The SQL clause that buckets rows by one or more columns so aggregates can be computed per bucket.", l:"core", g:["sql","query"],
 b:["`GROUP BY country` collapses all rows sharing a country into one output row, and any aggregate in the `SELECT` is computed within that bucket. Every non-aggregated column you select must be in the `GROUP BY` list, because otherwise the database would have to pick arbitrarily which value to show.",
    "Grouping happens after `WHERE` and before `HAVING`. `GROUPING SETS`, `ROLLUP` and `CUBE` extend it to produce subtotals and grand totals in a single pass."],
 k:["Every non-aggregated selected column must appear in GROUP BY.",
    "Runs after WHERE and before HAVING.",
    "`ROLLUP` and `CUBE` generate subtotals without extra queries.",
    "Grouping on an indexed column can avoid an expensive sort."],
 r:["Aggregate Function","DQL","Window Function"]},

{t:"NULL", d:"A marker meaning the value is unknown or absent — not zero, not an empty string.", l:"core", g:["sql","semantics"],
 b:["NULL is not a value; it is the absence of one, and it propagates through three-valued logic. `NULL = NULL` is not true, it is unknown, which is why you must write `IS NULL`. Any arithmetic involving NULL yields NULL, and `NOT IN (subquery containing NULL)` returns no rows at all — a bug that has confused every SQL developer at least once.",
    "Aggregates skip NULLs. `COALESCE` supplies a fallback. Deciding whether a column should permit NULL at all is a genuine modelling decision, not an afterthought."],
 k:["`IS NULL` / `IS NOT NULL` — never `= NULL`.",
    "Three-valued logic: true, false, unknown.",
    "`NOT IN` with a NULL in the set returns zero rows. Prefer `NOT EXISTS`.",
    "`COALESCE(col, fallback)` substitutes a default."],
 r:["Constraint","Null Safety","Aggregate Function"]},

{t:"NoSQL", d:"A family of databases that abandon the relational model to gain scale, flexibility or a better fit for a specific data shape.", l:"core", g:["database","nosql"],
 b:["NoSQL is a negative definition covering four quite different families: document stores (MongoDB), key-value stores (Redis, DynamoDB), wide-column stores (Cassandra, HBase) and graph databases (Neo4j). What they share is horizontal scaling and a flexible or absent schema.",
    "The trade-offs are real: weaker consistency guarantees, limited or no joins, and query patterns that must be decided up front because you design the storage layout around them. The industry has since converged — Postgres has excellent JSON support, and most NoSQL engines have added transactions — so the choice is far less binary than it was in 2012."],
 k:["Four families: document, key-value, wide-column, graph.",
    "Scale horizontally by design; relational engines mostly scale up.",
    "Schema flexibility moves validation into application code.",
    "Model around your query patterns, because ad-hoc queries are expensive or impossible."],
 r:["Document Database","Key-Value Store","Graph Database","CAP Theorem","Relational Database"]},

{t:"Document Database", d:"A NoSQL store that keeps self-contained JSON-like documents instead of rows spread across tables.", l:"intermediate", g:["nosql","database"],
 b:["A document holds an entire entity — a user with their addresses, preferences and order history nested inside — so reading it is one lookup with no joins. Documents in a collection need not share a shape, which suits evolving or genuinely heterogeneous data.",
    "The cost appears when the same nested data is needed from another angle, or when a value duplicated across ten thousand documents changes. MongoDB is the best-known engine; PostgreSQL's `JSONB` offers much of the same flexibility inside a relational database."],
 k:["One document = one entity, retrieved in a single read.",
    "No enforced schema, so validation lives in the application.",
    "Denormalised by nature, with the duplication that implies.",
    "PostgreSQL JSONB gives similar flexibility without giving up SQL."],
 x:{lang:"javascript", code:'db.users.insertOne({\n  _id: "u_1042",\n  name: "Ada Lovelace",\n  roles: ["admin", "engineer"],\n  address: { city: "London", postcode: "NW1" }\n});\n\ndb.users.find({ "address.city": "London", roles: "admin" });'},
 r:["MongoDB","NoSQL","JSON","Denormalisation"]},

{t:"Key-Value Store", d:"The simplest database model: a giant distributed dictionary mapping keys to opaque values.", l:"intermediate", g:["nosql","database"],
 b:["You put a value at a key and get it back by that key. There are no queries, no joins and usually no secondary indexes, and that constraint is exactly what makes the model fast and trivially shardable — the key determines the node.",
    "Redis, Memcached, DynamoDB and etcd are the common examples. It is the natural shape for caches, sessions, feature flags, rate-limit counters and any lookup where you always know the key."],
 k:["O(1) lookups by key; no ad-hoc querying.",
    "Shards cleanly because the key decides the partition.",
    "Perfect for caches, sessions, counters and feature flags.",
    "Access patterns must be known when you design the key."],
 r:["Redis","Caching","NoSQL","Sharding"]},

{t:"Wide-Column Store", d:"A NoSQL model storing data in rows whose columns can differ per row, partitioned across many nodes.", l:"advanced", g:["nosql","database"],
 b:["Cassandra and HBase organise data by partition key and clustering columns. Every row in a partition is stored together and sorted, so a query that reads a partition in order is extremely fast — and a query that does not match the partitioning is extremely slow or simply unsupported.",
    "This forces query-first design: you decide the read patterns, then create a table shaped for each one, duplicating data across tables. In exchange you get linear horizontal scaling and no single point of failure."],
 k:["Partition key decides placement; clustering columns decide sort order inside it.",
    "Query patterns must be known before the schema is written.",
    "The same data is duplicated across tables, one per access pattern.",
    "Masterless replication gives excellent write availability."],
 r:["Cassandra","NoSQL","Sharding","Partitioning"]},

{t:"Graph Database", d:"A database whose first-class citizens are nodes and the relationships between them.", l:"intermediate", g:["nosql","database"],
 b:["In a graph database a relationship is stored as a direct pointer, so traversing from one node to its neighbours is a constant-time hop regardless of how many nodes exist. Queries that would need five self-joins in SQL — friends of friends, fraud rings, supply chain dependencies, permission inheritance — become short traversals.",
    "Neo4j with Cypher is the reference implementation. The model is worth reaching for when the relationships are the thing you actually query, not merely a way to normalise."],
 k:["Relationships are stored, not computed by joining at query time.",
    "Traversal cost is independent of total dataset size.",
    "Cypher and Gremlin are the two common query languages.",
    "Best fit: recommendations, fraud detection, network and permission graphs."],
 x:{lang:"cypher", code:'MATCH (me:Person {name: "Ada"})-[:FRIEND]->()-[:FRIEND]->(fof)\nWHERE NOT (me)-[:FRIEND]->(fof) AND fof <> me\nRETURN fof.name, count(*) AS mutual\nORDER BY mutual DESC\nLIMIT 10;'},
 r:["Neo4j","NoSQL","Graph","Recommendation System"]},

{t:"Vector Database", d:"A database that indexes high-dimensional embedding vectors and retrieves the nearest ones to a query vector.", l:"core", g:["nosql","ai","search"],
 b:["Vector databases answer a different question from relational ones: not which rows match this filter, but which items are most similar to this one. They store embeddings and use approximate nearest neighbour indexes — HNSW, IVF, product quantisation — to search millions of vectors in milliseconds.",
    "This is the retrieval half of RAG. Pinecone, Weaviate, Qdrant, Milvis and Chroma are dedicated engines; pgvector adds the capability to PostgreSQL, which is often the pragmatic choice when you already run Postgres."],
 k:["Approximate nearest neighbour search trades a little recall for enormous speed.",
    "HNSW is the most common index: a navigable small-world graph.",
    "Cosine similarity or dot product are the usual distance metrics.",
    "Metadata filtering alongside vector search is what makes it usable in production."],
 x:{lang:"sql", code:'CREATE EXTENSION vector;\n\nCREATE TABLE docs (\n  id      BIGSERIAL PRIMARY KEY,\n  content TEXT,\n  embedding vector(1536)\n);\n\nCREATE INDEX ON docs USING hnsw (embedding vector_cosine_ops);\n\nSELECT content\nFROM docs\nORDER BY embedding <=> $1     -- cosine distance to the query vector\nLIMIT 5;'},
 dg:"embedding",
 r:["Embedding","Retrieval-Augmented Generation","Semantic Search","Cosine Similarity","Approximate Nearest Neighbour"]},

{t:"Time-Series Database", d:"A database optimised for data points that arrive in time order and are queried by time range.", l:"intermediate", g:["database","observability"],
 b:["Metrics, sensor readings, trades and logs share a shape: a timestamp, a set of labels, and a value; writes are append-only and overwhelmingly recent; queries ask for ranges and aggregates. Time-series databases exploit that with time-based partitioning, delta and dictionary compression, and automatic downsampling of older data.",
    "InfluxDB, TimescaleDB, Prometheus and ClickHouse all occupy this space. Compression ratios of 10x or better over a general-purpose store are normal."],
 k:["Append-only, time-ordered writes; range queries dominate reads.",
    "Aggressive compression through delta encoding of timestamps and values.",
    "Retention policies and downsampling keep old data affordable.",
    "Prometheus is the de facto standard for infrastructure metrics."],
 r:["Prometheus","Monitoring","Partitioning","ClickHouse"]},

{t:"CAP Theorem", d:"In a distributed system that experiences a network partition, you must choose between consistency and availability.", l:"intermediate", g:["distributed","theory"],
 b:["Consistency here means every read sees the latest write. Availability means every request gets a non-error response. Partition tolerance means the system keeps working when the network splits. Since networks do partition, partition tolerance is not optional — so the real choice is CP or AP.",
    "CP systems (etcd, ZooKeeper, Spanner) refuse to serve rather than serve stale data. AP systems (Cassandra, DynamoDB in its default mode) answer from whichever replica is reachable and reconcile later. PACELC extends the model: even without a partition you are trading latency against consistency."],
 k:["Partition tolerance is mandatory; the choice is really C versus A.",
    "CP: reject requests rather than return stale data.",
    "AP: always answer, reconcile afterwards.",
    "PACELC adds the latency-versus-consistency trade in the normal case."],
 dg:"cap",
 r:["ACID","BASE","Eventual Consistency","Distributed System"]},

{t:"Eventual Consistency", d:"A guarantee that replicas will converge on the same value if writes stop, without guaranteeing when.", l:"intermediate", g:["distributed","theory"],
 b:["Under eventual consistency a write to one replica propagates asynchronously. For a window — usually milliseconds, occasionally longer — different readers see different values. This is what allows a system to stay available during network trouble and to scale reads across regions.",
    "Read-your-own-writes, monotonic reads and causal consistency are stronger variants that fix the most user-visible weirdness (posting a comment and not seeing it) without paying for full linearisability."],
 k:["Replicas converge given time and no new writes.",
    "The staleness window is usually milliseconds but is not bounded.",
    "Read-your-writes consistency fixes the most jarring user-facing symptom.",
    "Conflict resolution needs a strategy: last-write-wins, vector clocks or CRDTs."],
 r:["CAP Theorem","BASE","Replication","Distributed System"]},

{t:"Sharding", d:"Splitting one logical dataset across multiple database servers, each holding a distinct subset.", l:"advanced", g:["scaling","distributed"],
 b:["When a single machine can no longer hold the data or serve the write volume, you shard: rows are routed to a shard by a shard key, usually hashed or ranged. Each shard is an independent database, so total capacity scales with the number of shards.",
    "The costs are severe and permanent. Cross-shard joins and transactions become application problems, a badly chosen shard key creates hot spots, and resharding a live system is a major project. Exhaust vertical scaling, read replicas and caching first."],
 k:["Shard key choice is the decision you cannot easily undo.",
    "Hash sharding spreads evenly; range sharding keeps ranges together but risks hot spots.",
    "Cross-shard joins and transactions largely stop being the database's problem.",
    "Try vertical scaling, replicas and caching before sharding."],
 r:["Replication","Partitioning","Horizontal Scaling","Distributed System"]},

{t:"Replication", d:"Maintaining copies of a database on multiple servers for redundancy, read scaling and failover.", l:"intermediate", g:["scaling","availability"],
 b:["In leader-follower replication one node accepts writes and streams its change log to followers that serve reads. If the leader dies, a follower is promoted. Multi-leader and leaderless designs allow writes anywhere at the cost of conflict resolution.",
    "The key parameter is synchronous versus asynchronous. Synchronous replication guarantees no data loss on failover but makes every write wait for a second machine. Asynchronous is fast but can lose the last few transactions — and creates replication lag, where a read replica returns data a moment behind the leader."],
 k:["Leader-follower is the default: writes to one node, reads from many.",
    "Synchronous means no data loss but higher write latency.",
    "Replication lag causes read-your-own-writes bugs — route those reads to the leader.",
    "Replicas are for availability and read scale, not a substitute for backups."],
 r:["Sharding","Eventual Consistency","High Availability","Backup"]},

{t:"Query Plan", a:"Execution Plan", d:"The step-by-step strategy the database chose to execute a query, and the first place to look when it is slow.", l:"intermediate", g:["performance","query"],
 b:["`EXPLAIN` shows the plan; `EXPLAIN ANALYZE` runs it and shows actual timings and row counts. You are looking for sequential scans on large tables, nested loops over many rows, and — most tellingly — a large gap between estimated and actual row counts, which means the statistics are stale.",
    "Reading plans is the difference between guessing at performance and knowing. Almost every dramatic query speed-up starts with someone actually reading the plan."],
 k:["`EXPLAIN ANALYZE` gives real timings and real row counts.",
    "Estimated versus actual rows diverging means statistics need refreshing.",
    "Sequential scan on a big table usually means a missing or unusable index.",
    "Plans change as data grows — a fast query today can degrade silently."],
 x:{lang:"sql", code:'EXPLAIN (ANALYZE, BUFFERS)\nSELECT * FROM orders\nWHERE customer_id = 42\n  AND created_at > now() - interval \'30 days\';\n\n-- Look for: Seq Scan, rows=  vs actual rows=, Buffers: read='},
 r:["Index","Query Optimiser","Full Table Scan","N+1 Query Problem"]},

{t:"Query Optimiser", d:"The database component that chooses how to execute a query, using statistics about the data.", l:"advanced", g:["performance","internals"],
 b:["A single SQL statement can be executed in many ways: which table to scan first, which index to use, whether to hash-join or nested-loop. The optimiser enumerates candidate plans, estimates each one's cost using table statistics, and picks the cheapest.",
    "It is only as good as its statistics. Stale statistics after a bulk load lead to catastrophically wrong plans, which is why `ANALYZE` matters. Query hints exist in some engines to override the optimiser, and should be a last resort — they freeze a decision that should adapt as data changes."],
 k:["Cost-based: it estimates and compares alternative plans.",
    "Depends on table statistics — run ANALYZE after bulk changes.",
    "Join order matters enormously and the optimiser chooses it for you.",
    "Hints override it and go stale; fix statistics or indexes instead."],
 r:["Query Plan","Index","Full Table Scan"]},

{t:"Full Table Scan", d:"Reading every row in a table because no usable index exists for the query.", l:"intermediate", g:["performance","query"],
 b:["A sequential scan is O(n) in the table size. On a thousand rows it is instant; on a hundred million it is a timeout. It appears when there is no index on the filtered column, when a function wraps the column (`WHERE LOWER(email) = ...` defeats a plain index on `email`), or when the optimiser judges that most rows match anyway.",
    "That last case is important: if a query returns 60% of the table, a scan genuinely is faster than an index lookup plus a million random reads. Not every sequential scan is a bug."],
 k:["O(n): fine on small tables, fatal on large ones.",
    "Wrapping a column in a function disables a plain index — use an expression index.",
    "Sometimes the correct choice when the query matches most of the table.",
    "Implicit type casts also silently prevent index use."],
 dg:"index-scan",
 r:["Index","Query Plan","B-Tree"]},

{t:"N+1 Query Problem", d:"Fetching a list with one query and then issuing one more query per item — turning a page load into hundreds of round trips.", l:"core", g:["performance","orm"],
 b:["You load 100 blog posts, then loop over them and access `post.author`, which lazily fires a query each time. One query becomes 101. Each is fast in isolation, so it hides in development with ten rows and falls over in production with ten thousand.",
    "The fix is eager loading — a join or a second query using `WHERE id IN (...)` — exposed as `include` in Rails, `selectinload` in SQLAlchemy, `JOIN FETCH` in JPA and DataLoader in GraphQL. Query logging in development is how you catch it early."],
 k:["One query for the list plus N for the children — network latency multiplies.",
    "Caused by lazy loading in ORMs, and by naive GraphQL resolvers.",
    "Fix with eager loading, a join, or a batched IN query.",
    "Log query counts per request in development; it is invisible otherwise."],
 x:{lang:"python", code:'# N+1: one query for posts, one per post for author\nfor post in session.query(Post).all():\n    print(post.author.name)\n\n# fixed: two queries total\nfrom sqlalchemy.orm import selectinload\nposts = session.query(Post).options(selectinload(Post.author)).all()'},
 r:["ORM","Query Plan","GraphQL","Caching"]},

{t:"ORM", a:"Object-Relational Mapping", d:"A library that maps database tables to objects in your programming language, generating SQL on your behalf.", l:"core", g:["tooling","backend"],
 b:["An ORM lets you write `user.orders.filter(status='paid')` instead of SQL, handles connection management and result mapping, and usually brings migrations along. Hibernate, SQLAlchemy, Entity Framework, Prisma, ActiveRecord and Django ORM are the well-known ones.",
    "The abstraction leaks under pressure. Generated SQL can be wildly inefficient, N+1 problems are easy to create accidentally, and complex analytical queries are usually clearer written by hand. The healthy position is to use the ORM for CRUD and drop to SQL when the query is the point."],
 k:["Removes boilerplate for the 80% of queries that are simple CRUD.",
    "Lazy loading is the main source of accidental N+1 problems.",
    "Always be able to see the SQL your ORM generates.",
    "Write complex analytical queries by hand; the ORM is not helping there."],
 r:["N+1 Query Problem","SQL","Database Migration","Connection Pool"]},

{t:"Connection Pool", d:"A cache of open database connections reused across requests instead of opening a new one each time.", l:"intermediate", g:["performance","backend"],
 b:["Establishing a database connection costs a TCP handshake, TLS negotiation and authentication — tens of milliseconds. A pool keeps a fixed set of connections open and hands them out, so the cost is paid once at startup.",
    "Pool sizing is counter-intuitive: bigger is usually worse. A database with 8 cores does not benefit from 200 concurrent connections; they contend and throughput drops. A common starting point is roughly (cores × 2) + effective spindle count. PgBouncer adds an external pooling layer for serverless and high-connection workloads."],
 k:["Avoids per-request handshake, TLS and auth overhead.",
    "Oversized pools reduce throughput through contention.",
    "Pool exhaustion presents as sudden timeouts under load.",
    "PgBouncer or RDS Proxy handle pooling for serverless functions."],
 r:["ORM","Rate Limiting","Serverless"]},

{t:"OLTP", a:"Online Transaction Processing", d:"Workloads made of many small, fast, concurrent reads and writes — the day-to-day operation of an application.", l:"intermediate", g:["workload","architecture"],
 b:["OLTP is what a normal application database does: insert an order, update a profile, fetch a cart. Queries touch few rows, must complete in milliseconds, and run at high concurrency. Row-oriented storage suits this, because reading one row means reading one contiguous block.",
    "Normalised schemas, plentiful indexes on selective columns, and short transactions are the design pattern. PostgreSQL, MySQL, SQL Server and Oracle are built primarily for it."],
 k:["Many small transactions, high concurrency, millisecond latency.",
    "Row-oriented storage; normalised schema; selective indexes.",
    "Optimised for writes and point lookups, not for scanning.",
    "Running big analytical queries here will hurt your users."],
 r:["OLAP","Relational Database","Transaction","Index"]},

{t:"OLAP", a:"Online Analytical Processing", d:"Workloads made of large scanning queries that aggregate across millions of rows for analysis and reporting.", l:"intermediate", g:["workload","analytics"],
 b:["OLAP queries touch few columns but enormous numbers of rows: revenue by region by quarter, funnel conversion over a year. Columnar storage is the enabler — reading three columns means reading three contiguous column files instead of every byte of every row — and it compresses far better because a column holds similar values.",
    "Snowflake, BigQuery, Redshift, ClickHouse and DuckDB are OLAP engines. Mixing OLAP queries into an OLTP database is a classic mistake; separating them is what a data warehouse is for."],
 k:["Few columns, huge row counts, seconds-to-minutes latency is acceptable.",
    "Columnar storage plus compression is the core technique.",
    "Denormalised star schemas rather than fully normalised ones.",
    "Keep it off your production OLTP database."],
 r:["OLTP","Data Warehouse","Columnar Storage","Star Schema"]},

{t:"Columnar Storage", d:"Storing each column's values together on disk instead of storing each row together.", l:"intermediate", g:["storage","analytics"],
 b:["In a row store, one row's fields are adjacent. In a column store, all values of one column are adjacent. An analytical query touching 3 of 200 columns reads only those three, cutting I/O by nearly 99%. Compression also improves dramatically, because a column of country codes or timestamps has far less entropy than a mixed row.",
    "The trade is that writing or reading a whole single row means touching every column file, so columnar is wrong for OLTP. Parquet, ORC, ClickHouse, DuckDB and every cloud warehouse use it."],
 k:["Reads only the columns the query mentions.",
    "Compresses far better because like values sit together.",
    "Enables vectorised execution over batches of values.",
    "Bad for single-row reads and writes — do not use it for OLTP."],
 r:["OLAP","Parquet","Data Warehouse","ClickHouse"]},

/* ---------- engines ---------- */

{t:"PostgreSQL", a:"Postgres", d:"An open-source relational database known for standards compliance, extensibility and being the sensible default.", l:"core", g:["engine","relational"],
 b:["Postgres has quietly become the default choice for new projects. It offers full ACID transactions, sophisticated indexing (B-tree, GIN, GiST, BRIN, HNSW via pgvector), window functions, CTEs, JSONB with indexing, full-text search, and an extension system that lets it absorb whole new capabilities.",
    "That extensibility means one Postgres instance can often replace a separate document store, search engine and vector database — with real transactions across all of it. PostGIS for geospatial and TimescaleDB for time series are the standout extensions."],
 k:["MVCC gives readers a consistent snapshot without blocking writers.",
    "JSONB is indexable, so semi-structured data does not need a second database.",
    "Extensions: PostGIS, pgvector, TimescaleDB, pg_stat_statements.",
    "Watch out for connection overhead — use a pooler."],
 r:["MySQL","SQL","Relational Database","Vector Database"]},

{t:"MySQL", d:"The most widely deployed open-source relational database, and the M in the classic LAMP stack.", l:"core", g:["engine","relational"],
 b:["MySQL earned its position through speed on simple read-heavy workloads and easy operation. InnoDB, the default storage engine since 5.5, provides ACID transactions, row-level locking and foreign keys. Version 8 added window functions, CTEs and a proper JSON type.",
    "It remains slightly behind PostgreSQL on advanced SQL features and strictness, and historically shipped with permissive defaults that silently truncated data. MariaDB is a community fork that diverged after Oracle's acquisition."],
 k:["Use InnoDB; MyISAM has no transactions and no foreign keys.",
    "Default isolation is Repeatable Read, unlike Postgres.",
    "Check `sql_mode` — older permissive defaults truncate data silently.",
    "Excellent replication tooling and a very large operational knowledge base."],
 r:["PostgreSQL","SQL","Relational Database"]},

{t:"SQLite", d:"An embedded relational database that lives in a single file, with no server process at all.", l:"core", g:["engine","embedded"],
 b:["SQLite is a C library your application links against; the whole database is one file. It is almost certainly the most deployed database in the world — it is in every phone, browser, operating system and countless applications — and it is public domain with an extraordinarily thorough test suite.",
    "It supports most of SQL, full transactions and WAL mode for concurrent readers. Its limit is a single writer at a time, which rules out write-heavy multi-user servers but is irrelevant for local storage, tests, and read-heavy small sites."],
 k:["Zero configuration, zero server, one portable file.",
    "One writer at a time; many concurrent readers in WAL mode.",
    "Dynamic typing with type affinity — unusual for SQL.",
    "Ideal for local apps, tests, caches and edge deployments."],
 r:["PostgreSQL","Relational Database","SQL"]},

{t:"MongoDB", d:"The best-known document database, storing BSON documents in schemaless collections.", l:"intermediate", g:["engine","nosql"],
 b:["MongoDB stores JSON-like documents with a flexible schema, scales horizontally through sharding, and offers a rich aggregation pipeline for transformations. Since version 4 it supports multi-document ACID transactions, closing the biggest historical gap with relational engines.",
    "It suits genuinely document-shaped data with well-understood access patterns. It suits highly relational data poorly — teams that reach for `$lookup` constantly have usually chosen the wrong tool."],
 k:["Documents in collections, no enforced schema by default.",
    "The aggregation pipeline is its equivalent of complex SQL.",
    "Multi-document ACID transactions since 4.0.",
    "Frequent `$lookup` joins are a signal the data is actually relational."],
 r:["Document Database","NoSQL","Sharding","JSON"]},

{t:"Redis", d:"An in-memory data structure store used as a cache, message broker and low-latency database.", l:"core", g:["engine","cache","nosql"],
 b:["Redis keeps everything in RAM and answers in microseconds. It is not just a key-value store — it has native lists, sets, sorted sets, hashes, bitmaps, HyperLogLogs and streams, which is what makes it good for leaderboards, rate limiters, queues and session stores as well as caching.",
    "Persistence is optional (RDB snapshots and AOF logs), so it can be durable, but treating it as the system of record is a decision to make consciously. Commands are executed on a single thread, which makes them atomic and also means one slow command blocks everything — never run `KEYS *` in production."],
 k:["Microsecond latency because everything lives in memory.",
    "Rich types: sorted sets power leaderboards, streams power queues.",
    "Single-threaded command execution gives atomicity — and blocking risk.",
    "Set an eviction policy and TTLs, or memory will fill and writes will fail."],
 x:{lang:"bash", code:'SET session:abc123 "{\\"user\\":42}" EX 3600   # expires in an hour\nINCR ratelimit:ip:1.2.3.4\nEXPIRE ratelimit:ip:1.2.3.4 60\nZADD leaderboard 4200 "player:7"\nZREVRANGE leaderboard 0 9 WITHSCORES'},
 r:["Caching","Key-Value Store","Message Queue","Rate Limiting"]},

{t:"Cassandra", a:"Apache Cassandra", d:"A masterless wide-column store built for enormous write throughput and no single point of failure.", l:"advanced", g:["engine","nosql","distributed"],
 b:["Every Cassandra node is equal — there is no leader — so any node can accept a write and the cluster survives losing several. Writes go to an append-only commit log and memtable, making them extremely fast. Tunable consistency lets you choose per query how many replicas must acknowledge.",
    "The cost is rigid data modelling: you design a table per query pattern, and queries that do not match the partition key are unsupported. It shines at time-series, event logging and messaging at very large scale."],
 k:["Masterless: no single point of failure, linear scale-out.",
    "Tunable consistency per query — ONE, QUORUM, ALL.",
    "One table per query pattern; duplication is the design, not a smell.",
    "Beware tombstones from heavy deletes — they degrade reads badly."],
 r:["Wide-Column Store","NoSQL","Eventual Consistency","Sharding"]},

{t:"DynamoDB", d:"AWS's fully managed key-value and document database with predictable single-digit millisecond latency at any scale.", l:"intermediate", g:["engine","nosql","cloud"],
 b:["DynamoDB removes operations entirely: no servers, no version upgrades, automatic partitioning. You define a partition key (and optionally a sort key), and it scales to any throughput. Access is by key or by index — there is no ad-hoc querying.",
    "Single-table design, where multiple entity types share one table with carefully constructed composite keys, is the idiomatic pattern and takes real effort to learn. Cost is driven by read and write capacity units, so a bad access pattern is expensive as well as slow."],
 k:["Partition key determines physical placement — choose it for even distribution.",
    "No ad-hoc queries: every access path needs a key or a secondary index.",
    "Single-table design is idiomatic and unintuitive at first.",
    "Hot partitions throttle; billing follows access patterns closely."],
 r:["Key-Value Store","NoSQL","Sharding"]},

{t:"Neo4j", d:"The leading graph database, with the Cypher query language for expressing traversals.", l:"advanced", g:["engine","graph"],
 b:["Neo4j stores nodes and relationships natively with index-free adjacency, meaning each node holds direct references to its relationships. Traversing a hop is a pointer dereference, so multi-hop queries stay fast no matter how large the graph grows.",
    "Cypher's ASCII-art pattern syntax — `(a)-[:KNOWS]->(b)` — makes traversals genuinely readable. It is used for fraud rings, recommendations, network topology, identity graphs and knowledge graphs."],
 k:["Index-free adjacency makes traversal cost independent of graph size.",
    "Cypher patterns read like the picture you would draw on a whiteboard.",
    "ACID transactions, unlike most NoSQL stores.",
    "Strong fit for knowledge graphs feeding LLM retrieval."],
 r:["Graph Database","Graph","Knowledge Graph"]},

{t:"Elasticsearch", d:"A distributed search and analytics engine built on Lucene, designed for full-text search over large document sets.", l:"intermediate", g:["engine","search"],
 b:["Elasticsearch builds inverted indexes: for each term, a list of documents containing it. That is what makes searching millions of documents for a phrase instantaneous, with relevance scoring, fuzzy matching, faceting and highlighting on top.",
    "It is also widely used for log aggregation as the E in the ELK stack. It is a search engine, not a system of record — treat it as a derived index you can rebuild from your primary database."],
 k:["Inverted index maps terms to documents, enabling fast full-text search.",
    "Analysers control tokenisation, stemming and stop words per field.",
    "BM25 relevance scoring by default; kNN vector search is now supported too.",
    "Not a source of truth — always be able to reindex from the primary store."],
 r:["Full-Text Search","Inverted Index","Semantic Search","Logging"]},

{t:"ClickHouse", d:"An open-source columnar database built for extremely fast analytical queries over huge datasets.", l:"advanced", g:["engine","analytics"],
 b:["ClickHouse combines columnar storage, aggressive compression, vectorised execution and parallelism across cores and nodes. Scanning billions of rows in under a second on modest hardware is its normal operating mode.",
    "It is optimised for append-heavy analytical workloads; updates and deletes are possible but awkward, and it has no real transactions. It is a common choice for product analytics, observability backends and real-time dashboards."],
 k:["Columnar plus vectorised execution over batches of values.",
    "MergeTree engines sort and merge data in the background.",
    "Appends are cheap; updates and deletes are not its strength.",
    "Materialised views compute rollups incrementally at insert time."],
 r:["OLAP","Columnar Storage","Data Warehouse","Time-Series Database"]},

{t:"Snowflake", d:"A cloud data warehouse that separates storage from compute so each scales independently.", l:"intermediate", g:["engine","warehouse","cloud"],
 b:["Snowflake's architecture keeps data in cloud object storage and runs queries on virtual warehouses — compute clusters you can start, resize and stop independently. Two teams can run heavy queries simultaneously on separate warehouses without competing for resources.",
    "Zero-copy cloning creates an instant, storage-free copy of a database for testing, and time travel lets you query the state of a table as of an earlier moment. Billing is per second of compute, which rewards efficient queries and punishes forgotten idle warehouses."],
 k:["Storage and compute are decoupled and billed separately.",
    "Virtual warehouses isolate workloads from each other.",
    "Zero-copy cloning and time travel are genuinely useful operationally.",
    "Auto-suspend idle warehouses or the bill will surprise you."],
 r:["Data Warehouse","OLAP","BigQuery","Columnar Storage"]},

{t:"BigQuery", d:"Google Cloud's serverless data warehouse, where you run SQL over petabytes without managing any infrastructure.", l:"intermediate", g:["engine","warehouse","cloud"],
 b:["BigQuery has no clusters to size. You load data and run SQL; Google allocates thousands of workers behind the scenes. Pricing is either per byte scanned or by reserved capacity, which makes partitioning and clustering directly financial decisions.",
    "It integrates tightly with the rest of Google Cloud, supports geospatial and ML functions in SQL, and can query external data in Cloud Storage or Sheets without loading it."],
 k:["Fully serverless — no nodes, no sizing, no maintenance windows.",
    "On-demand pricing is per byte scanned: `SELECT *` costs real money.",
    "Partition by date and cluster by filter columns to cut scanned bytes.",
    "BigQuery ML trains models directly in SQL."],
 r:["Data Warehouse","Snowflake","OLAP","Partitioning"]},

{t:"Full-Text Search", d:"Searching the words inside documents rather than matching an exact column value.", l:"intermediate", g:["search","query"],
 b:["Full-text search tokenises text, normalises it (lowercasing, stemming, removing stop words) and builds an inverted index from terms to documents. Ranking functions such as BM25 then order results by relevance rather than by any column.",
    "A `LIKE '%term%'` query cannot use a standard index and scans everything, which is why it fails past a few thousand rows. Postgres offers `tsvector` and GIN indexes natively; Elasticsearch and OpenSearch are the dedicated engines."],
 k:["Inverted index: term → list of documents containing it.",
    "Stemming and stop words make search match meaning, not exact strings.",
    "BM25 is the standard relevance ranking function.",
    "`LIKE '%x%'` cannot use an index — never build search on it."],
 r:["Elasticsearch","Inverted Index","Semantic Search","Index"]},

{t:"Inverted Index", d:"A mapping from each term to the list of documents that contain it — the data structure behind search engines.", l:"intermediate", g:["search","data-structure"],
 b:["A forward index maps document → terms. Inverting it gives term → documents, which is exactly the direction a search query needs. Looking up two terms and intersecting their posting lists answers a two-word query without touching any other document.",
    "Postings usually store positions too, enabling phrase search, and are compressed heavily since document ids can be delta-encoded. Lucene, and therefore Elasticsearch and Solr, are built on this structure."],
 k:["Term → posting list of document ids (plus positions and frequencies).",
    "Intersecting posting lists answers multi-term queries efficiently.",
    "Delta encoding compresses sorted document ids dramatically.",
    "Positions in the postings enable phrase and proximity search."],
 r:["Full-Text Search","Elasticsearch","Index","Tokenisation"]},

{t:"Backup", d:"A copy of the database kept separately so data can be restored after loss, corruption or a bad deployment.", l:"core", g:["operations","reliability"],
 b:["Backups come in two forms: logical dumps (`pg_dump`, `mysqldump`) which are portable and slow, and physical snapshots which are fast and engine-specific. Continuous archiving of the write-ahead log enables point-in-time recovery — restoring to any moment, including one second before a mistaken `DELETE`.",
    "The only meaningful measure of a backup is whether a restore has been tested. Untested backups fail at exactly the moment you need them, and replication is not a backup: a dropped table replicates instantly."],
 k:["Test restores on a schedule — an untested backup is a hope, not a plan.",
    "Replication is not backup: it replicates your mistakes faithfully.",
    "Point-in-time recovery needs continuous WAL archiving.",
    "Know your RPO (how much data you can lose) and RTO (how long recovery takes)."],
 r:["Replication","Disaster Recovery","High Availability"]},

{t:"Optimistic Locking", d:"Allowing concurrent edits and detecting conflicts at write time using a version number, instead of locking rows in advance.", l:"intermediate", g:["concurrency","transaction"],
 b:["Each row carries a version column. When you update, you include `WHERE version = <the version you read>` and increment it. If zero rows are affected, someone else changed the row since you read it, and you handle the conflict — usually by reloading and retrying or by telling the user.",
    "This suits web applications, where a user might hold a form open for minutes. Pessimistic locking (`SELECT ... FOR UPDATE`) is the alternative, correct when conflicts are frequent and retries are expensive."],
 k:["No locks held between read and write — good for long user think-time.",
    "Conflict detected by an affected-row count of zero.",
    "Pessimistic locking is better when contention is genuinely high.",
    "ETags and `If-Match` headers are the same idea over HTTP."],
 x:{lang:"sql", code:'UPDATE documents\n   SET body = $1,\n       version = version + 1\n WHERE id = $2\n   AND version = $3;   -- version read earlier\n-- 0 rows affected => someone else edited it first'},
 r:["Isolation Level","Transaction","Race Condition","Deadlock"]}

]);
